1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15	)
16	
17	// on-disk layout inside the data directory:
18	//
19	//	data.json    – the committed state (JSON envelope, atomically replaced)
20	//	data.json.tmp– staging file for the next commit (rename(2) target)
21	//	lock         – flock file serializing concurrent processes
22	//
23	// The envelope carries an explicit format version: files written by an
24	// incompatible future build are refused rather than silently migrated or
25	// overwritten.
26	const (
27		dirDataFile = "data.json"
28		dirTmpFile  = "data.json.tmp"
29		dirLockFile = "lock"
30	
31		// FormatVersion is the on-disk format this build writes and accepts.
32		FormatVersion = 1
33	)
34	
35	// envelope is the persisted state container.
36	//
37	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
38	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
39	// decides what a committed circuit record may look like. UnmarshalJSON first
40	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
41	// object key anywhere encoding/json would otherwise keep the last value. At
42	// the envelope's top level that comparison is case-insensitive for the five
43	// known fields (format/circuits/setups/jobs/artifacts): a second spelling
44	// that differs only in ASCII letter case — including one JSON-escaped — names
45	// the same field and corrupts the read instead of overriding it. A spelling
46	// that Unicode case-folds onto one of those fields yet is not an ASCII case
47	// variant ("circuitſ" with U+017F long s, directly written or ſ-escaped)
48	// is likewise corruption even when it is the only spelling present, since
49	// encoding/json's own tag matching would fill the field from it; a later
50	// "circuitſ": [] must never read the circuits as empty and drop them on the
51	// next commit.
52	type envelope struct {
53		Format    int               `json:"format"`
54		Circuits  []persistCircuit  `json:"circuits"`
55		Setups    []persistSetup    `json:"setups"`
56		Jobs      []persistJob      `json:"jobs"`
57		Artifacts []persistArtifact `json:"artifacts,omitempty"`
58	}
59	
60	// envelopeWire is the decoding-only shape: circuit records arrive raw so
61	// their own strict decoder can require every field explicitly.
62	type envelopeWire struct {
63		Format    int               `json:"format"`
64		Circuits  []json.RawMessage `json:"circuits"`
65		Setups    []persistSetup    `json:"setups"`
66		Jobs      []persistJob      `json:"jobs"`
67		Artifacts []persistArtifact `json:"artifacts,omitempty"`
68	}
69	
70	func (e *envelope) UnmarshalJSON(raw []byte) error {
71		// Reject repeated keys before decoding: encoding/json silently keeps the
72		// last value of a duplicate. The walk is layered so a repeated field is
73		// attributed to the record it belongs to (a duplicate "frozen" inside
74		// circuit #3, not a generic envelope complaint).
75		if err := scanEnvelopeDuplicates(raw); err != nil {
76			return err
77		}
78		var wire envelopeWire
79		if err := json.Unmarshal(raw, &wire); err != nil {
80			var se StoreError
81			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
82				return err // an inner record decoder already named the problem
83			}
84			return corruptf("data file envelope is not valid JSON: %v", err)
85		}
86		e.Format = wire.Format
87		e.Setups = wire.Setups
88		e.Jobs = wire.Jobs
89		e.Artifacts = wire.Artifacts
90		if wire.Circuits == nil {
91			e.Circuits = nil
92		} else {
93			e.Circuits = make([]persistCircuit, len(wire.Circuits))
94		}
95		for i, craw := range wire.Circuits {
96			var record persistCircuit
97			if err := json.Unmarshal(craw, &record); err != nil {
98				var se StoreError
99				if errors.As(err, &se) {
100					// Re-tag as one corruption error carrying the record index,
101					// so the detail survives errors.As unwrapping in loadLocked.
102					return StoreError{Kind: ErrDataCorrupt.Kind,
103						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
104				}
105				return corruptf("circuit record #%d: %v", i+1, err)
106			}
107			e.Circuits[i] = record
108		}
109		return nil
110	}
111	
112	// envelopeTopFields are the five fields an envelope may carry. Their
113	// canonical (standard lowercase) spellings are the wire tags on envelope and
114	// envelopeWire; JSON keys are tokenized after unescaping.
115	var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}
116	
117	// canonicalEnvelopeField reports the standard lowercase name of one of the
118	// five envelope fields when key names it under any ASCII letter-case spelling
119	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
120	// tokenizer, so an escaped spelling of any such form lands here too. A
121	// non-canonical key (different length or a mismatching byte, including
122	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
123	func canonicalEnvelopeField(key string) string {
124		for _, field := range envelopeTopFields {
125			if len(key) != len(field) {
126				continue
127			}
128			i := 0
129			for i < len(key) {
130				c := key[i]
131				if c >= 'A' && c <= 'Z' {
132					c += 'a' - 'A'
133				}
134				if c != field[i] {
135					break
136				}
137				i++
138			}
139			if i == len(field) {
140				return field
141			}
142		}
143		return ""
144	}
145	
146	// envelopeFieldLookalike reports the standard lowercase name of one of the
147	// five envelope fields when key names it under a spelling encoding/json's
148	// struct-tag matching would fold onto the field but which is not an accepted
149	// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
150	// matching folds with the Unicode simple case-folding rules
151	// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
152	// the JSON escape u017f — keys arrive here already unescaped) names the
153	// circuits field exactly like "circuits", even standing alone. Such a
154	// lookalike is damage whatever its value: a later "circuitſ": [] would
155	// otherwise override a populated circuits array through last-value-wins and
156	// the records would vanish on the next commit. A key that does not fold onto
157	// any known field — an unrelated unknown name such as "note", or "cİrcuits"
158	// with U+0130 dotted capital I, which does not fold — returns "" and keeps
159	// the ordinary unknown-member handling.
160	func envelopeFieldLookalike(key string) string {
161		if canonicalEnvelopeField(key) != "" {
162			return "" // an accepted ASCII spelling, not a lookalike
163		}
164		for _, field := range envelopeTopFields {
165			if strings.EqualFold(key, field) {
166				return field
167			}
168		}
169		return ""
170	}
171	
172	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
173	// repeated object key. The five known top-level fields are identified case-
174	// insensitively: two spellings that differ only in ASCII letter case (both
175	// keys already JSON-unescaped at this point) are the same field, in whatever
176	// order they appear and whether or not their values agree, so a later
177	// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
178	// json's last-value-wins struct matching. Such a pair is reported as a
179	// duplicated top-level field named by its standard lowercase spelling.
180	//
181	// A non-ASCII spelling that folds onto a known field but is not an ASCII case
182	// variant ("circuitſ", "setupſ", "jobſ", "artifactſ" with U+017F long s,
183	// directly written or ſ-escaped) is rejected outright as data corruption:
184	// encoding/json would match it onto the field, so ignoring it as unknown
185	// could let its value replace the real one (an empty array hiding every
186	// record), and accepting it would let the records vanish on the next commit.
187	// The rule holds for the lookalike appearing alone — value a legal record, an
188	// empty array or null alike — and for it appearing beside the canonical
189	// spelling or an ASCII case variant, in either order and whether the values
190	// agree. The error names both the standard field and the actual spelling.
191	//
192	// Circuit, setup and job records are scanned one record at a time through
193	// their shared per-record readers — the record's own top-level keys are
194	// checked here (with the record's 1-based index, or the job's id, reported)
195	// by scanCircuitArray, scanSetupArray in setup_record.go and the shared job
196	// reader scanJobArray in job_record.go, while a nested value such as a
197	// constraint definition or an unknown member's object is skipped and left to
198	// its own strict decoder. Every other envelope member is scanned recursively
199	// so a duplicated key anywhere in committed data fails the read instead of
200	// silently resolving to its last value.
201	func scanEnvelopeDuplicates(raw []byte) error {
202		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
203		dec.UseNumber()
204		open, err := dec.Token()
205		if err != nil || open != json.Delim('{') {
206			return corruptf("data file envelope must be a JSON object")
207		}
208		// Exact spellings retain the pre-existing check for unknown keys;
209		// canonical names remember a known field's first occurrence regardless
210		// of the case it was written in.
211		seenTop := make(map[string]bool)
212		seenCanonical := make(map[string]bool)
213		for dec.More() {
214			keyTok, err := dec.Token()
215			if err != nil {
216				return corruptf("data file envelope is not valid JSON: %v", err)
217			}
218			key, ok := keyTok.(string)
219			if !ok {
220				return corruptf("data file envelope is not valid JSON")
221			}
222			// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
223			// matching would read as a known field ("circuitſ" with long s,
224			// directly written or ſ-escaped) before anything else. It is damage
225			// even on its own and whatever its value — a legal record, an empty
226			// array or null — and whether it precedes or follows the canonical or
227			// an ASCII case-variant spelling: the read may neither ignore it as an
228			// unknown member nor choose one of the values and carry on.
229			if canonical := envelopeFieldLookalike(key); canonical != "" {
230				return corruptf("data file envelope carries top-level field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
231					canonical, key)
232			}
233			if canonical := canonicalEnvelopeField(key); canonical != "" {
234				if seenCanonical[canonical] {
235					if key == canonical {
236						return corruptf("data file envelope contains duplicate top-level field %q", canonical)
237					}
238					return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
239						canonical, key)
240				}
241				seenCanonical[canonical] = true
242				if canonical == "circuits" {
243					if err := scanCircuitArray(dec); err != nil {
244						return err
245					}
246					continue
247				}
248				if canonical == "jobs" {
249					if err := scanJobArray(dec); err != nil {
250						return err
251					}
252					continue
253				}
254				if canonical == "setups" {
255					if err := scanSetupArray(dec); err != nil {
256						return err
257					}
258					continue
259				}
260				if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
261					return err
262				}
263				continue
264			}
265			if seenTop[key] {
266				return corruptf("data file envelope contains duplicate field %q", key)
267			}
268			seenTop[key] = true
269			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
270				return err
271			}
272		}
273		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
274			return corruptf("data file envelope is not valid JSON")
275		}
276		if _, err := dec.Token(); err != io.EOF {
277			return corruptf("data file envelope is not valid JSON: trailing data after the object")
278		}
279		return nil
280	}
281	
282	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
283	// recursively rejecting duplicate object keys.
284	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
285		tok, err := dec.Token()
286		if err != nil {
287			return corruptf("%s is not valid JSON: %v", what, err)
288		}
289		delim, ok := tok.(json.Delim)
290		if !ok {
291			return nil // scalar (including null)
292		}
293		switch delim {
294		case '{':
295			seen := make(map[string]bool)
296			for dec.More() {
297				keyTok, err := dec.Token()
298				if err != nil {
299					return corruptf("%s is not valid JSON: %v", what, err)
300				}
301				key, ok := keyTok.(string)
302				if !ok {
303					return corruptf("%s is not valid JSON", what)
304				}
305				if seen[key] {
306					return corruptf("%s contains duplicate field %q", what, key)
307				}
308				seen[key] = true
309				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
310					return err
311				}
312			}
313			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
314				return corruptf("%s is not valid JSON", what)
315			}
316		case '[':
317			index := 0
318			for dec.More() {
319				index++
320				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
321					return err
322				}
323			}
324			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
325				return corruptf("%s is not valid JSON", what)
326			}
327		}
328		return nil
329	}
330	
331	type persistTerm struct {
332		Wire  int    `json:"wire"`
333		Coeff string `json:"coeff"`
334	}
335	
336	type persistConstraint struct {
337		A []persistTerm `json:"a"`
338		B []persistTerm `json:"b"`
339		C []persistTerm `json:"c"`
340	}
341	
342	// persistDefinition is the canonical, already-validated constraint set bound
343	// to one circuit version. The public/private partition is owned by the
344	// circuit record and is deliberately not duplicated here, so it can never
345	// drift from the declared counts.
346	type persistDefinition struct {
347		Modulus     string              `json:"modulus"`
348		Constraints []persistConstraint `json:"constraints"`
349	}
350	
351	// persistArtifact is a compiled artifact: the version's identity and
352	// constraint count bound to its recomputable SHA-256 hash.
353	type persistArtifact struct {
354		Name        string `json:"name"`
355		Version     int    `json:"version"`
356		Modulus     int64  `json:"modulus"`
357		Constraints int    `json:"constraints"`
358		Hash        string `json:"hash"`
359	}
360	
361	// Store is a persistent workbench backed by one local data directory.
362	//
363	// All operations are safe for concurrent use by multiple goroutines and by
364	// several processes pointed at the same directory: an in-process mutex plus a
365	// process-shared flock serialize commits, and every commit is an atomic
366	// temp-file/fsync/rename replacement. Open the directory with Open and call
367	// Close when done.
368	type Store struct {
369		dir  string
370		mu   sync.Mutex
371		lock *os.File
372	
373		data envelope
374	}
375	
376	// resolveDataDir turns the Open argument into the absolute physical
377	// directory the store will be permanently pinned to.
378	//
379	// The argument is resolved exactly the way the kernel reaches it on an
380	// open(2) — relative components anchored to the process's current working
381	// directory at Open time, one component at a time, every symlink expanded at
382	// the position where the walk meets it. No lexical Clean is applied first:
383	// filepath.Abs/Clean would fold "entry/.." before the symlink was ever
384	// examined, so a ".." standing after a symlink pops the link's resolved
385	// target rather than the link's own spelling, and a/link/../x cannot be made
386	// to name a/x and select another data directory. Any trailing segment that
387	// does not exist yet (a data directory to be created by Open, or a
388	// not-yet-existing parent) is appended verbatim to the resolved physical
389	// prefix, and MkdirAll creates it beneath that prefix; a ".." after such a
390	// missing component cannot be walked faithfully (the kernel reports ENOENT
391	// there instead of folding the literal path) and fails the resolution. A
392	// dangling entry link — the entry itself is a symlink whose target does not
393	// exist — resolves through the link target's spelling and is created there.
394	func resolveDataDir(dir string) (string, error) {
395		resolved, err := resolveExistingPrefix(dir)
396		if err != nil {
397			return "", err
398		}
399		if !filepath.IsAbs(resolved) {
400			// The walk itself stayed relative to the Open-time working directory;
401			// only now, after every symlink has been expanded and every ".."
402			// popped in walk order, anchor the result absolutely for pinning.
403			resolved, err = filepath.Abs(resolved)
404			if err != nil {
405				return "", err
406			}
407		}
408		return resolved, nil
409	}
410	
411	// maxDataDirLinks bounds symlink expansion while resolving the data
412	// directory, matching the kernel's ELOOP guard: a link cycle must fail Open
413	// rather than loop forever.
414	const maxDataDirLinks = 255
415	
416	// resolveExistingPrefix walks path the way a kernel path walk reaches it,
417	// accepting both absolute and Open-cwd-relative paths. Symlinks are expanded
418	// inline where the walk meets them and ".." pops the directory the walk is
419	// actually standing in (a link target, not the link spelling). Unlike
420	// filepath.EvalSymlinks the walk tolerates a missing tail: at the first
421	// component that cannot be Lstat'd, that component and the remaining literal
422	// components are appended to the resolved prefix so Open can create the chain
423	// with MkdirAll — unless the remainder contains "..", which could not be
424	// resolved against a non-existent entry and is an error.
425	func resolveExistingPrefix(path string) (string, error) {
426		volLen := len(filepath.VolumeName(path))
427		pathSeparator := string(os.PathSeparator)
428		if volLen < len(path) && os.IsPathSeparator(path[volLen]) {
429			volLen++
430		}
431		vol := path[:volLen] // "/" (or a drive/UNC root elsewhere); "" when relative
432		dest := vol
433		linksWalked := 0
434		for start, end := volLen, volLen; start < len(path); start = end {
435			for start < len(path) && os.IsPathSeparator(path[start]) {
436				start++
437			}
438			end = start
439			for end < len(path) && !os.IsPathSeparator(path[end]) {
440				end++
441			}
442			if end == start {
443				break
444			}
445			comp := path[start:end]
446			if comp == "." {
447				continue
448			}
449			if comp == ".." {
450				// Pop what the walk has actually reached; symlinks have already
451				// been expanded into dest, so this removes the target, never the
452				// link spelling.
453				r := -1
454				for i := len(dest) - 1; i >= volLen; i-- {
455					if os.IsPathSeparator(dest[i]) {
456						r = i
457						break
458					}
459				}
460				if r < volLen || dest[r+1:] == ".." {
461					if len(dest) > volLen {
462						dest += pathSeparator
463					}
464					dest += ".."
465				} else {
466					dest = dest[:r]
467				}
468				continue
469			}
470	
471			if len(dest) > len(filepath.VolumeName(dest)) && !os.IsPathSeparator(dest[len(dest)-1]) {
472				dest += pathSeparator
473			}
474			dest += comp
475	
476			fi, err := os.Lstat(dest)
477			if err != nil {
478				if !os.IsNotExist(err) {
479					return "", err
480				}
481				// Missing tail: append the remainder literally, refusing a
482				// remainder containing ".." (unresolvable against this absent
483				// entry), and let MkdirAll create the chain.
484				for r := end; r < len(path); {
485					for r < len(path) && os.IsPathSeparator(path[r]) {
486						r++
487					}
488					s := r
489					for r < len(path) && !os.IsPathSeparator(path[r]) {
490						r++
491					}
492					switch path[s:r] {
493					case "", ".":
494					case "..":
495						return "", fmt.Errorf("cannot resolve %q: %q does not exist and is followed by a parent reference", path, comp)
496					default:
497						dest += pathSeparator + path[s:r]
498					}
499				}
500				return filepath.Clean(dest), nil
501			}
502			if fi.Mode()&os.ModeSymlink == 0 {
503				if !fi.Mode().IsDir() && end < len(path) {
504					return "", fmt.Errorf("cannot resolve %q: %q is not a directory", path, comp)
505				}
506				continue
507			}
508			linksWalked++
509			if linksWalked > maxDataDirLinks {
510				return "", fmt.Errorf("cannot resolve %q: too many symlinks", path)
511			}
512			link, err := os.Readlink(dest)
513			if err != nil {
514				return "", err
515			}
516			// Expand the link exactly at the walk position: the still-queued
517			// components (including any "..") continue from the target rather
518			// than from the link spelling.
519			path = link + path[end:]
520			switch {
521			case len(link) > 0 && os.IsPathSeparator(link[0]):
522				volLen = 1
523				vol = path[:1]
524				dest = vol
525				end = 1
526			default:
527				if v := filepath.VolumeName(link); v != "" {
528					if len(link) > len(v) && os.IsPathSeparator(link[len(v)]) {
529						v += string(os.PathSeparator)
530					}
531					volLen = len(v)
532					vol = v
533					dest = vol
534					end = volLen
535					break
536				}
537				// Relative link: it names a path from the directory holding the
538				// link, which is dest without the link's own component.
539				r := -1
540				for i := len(dest) - 1; i >= volLen; i-- {
541					if os.IsPathSeparator(dest[i]) {
542						r = i
543						break
544					}
545				}
546				if r < volLen {
547					dest = vol
548				} else {
549					dest = dest[:r]
550				}
551				end = 0
552			}
553		}
554		return filepath.Clean(dest), nil
555	}
556	
557	// Open opens (creating if needed) the workbench data in dir. If the
558	// directory does not exist it is created. Existing committed data is loaded
559	// and fully validated before Open returns; on a corrupt, truncated or
560	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
561	// leaves every file in the directory untouched.
562	//
563	// dir is resolved against the process's current working directory at Open
564	// time and pinned for the store's lifetime: a relative path such as
565	// "bench-data" names one fixed directory from the moment Open succeeds, and
566	// later working-directory changes never redirect the store's reads, writes,
567	// lock or Dir to another location.
568	//
569	// The pinning is to the actual directory opened, not to the literal path
570	// spelling: symlinks already present in the file system — whether dir itself
571	// is a link or one of its parent directories is — are resolved segment by
572	// segment at Open time, and Dir reports the resulting absolute physical
573	// directory. Repointing or removing an entry link afterwards never moves the
574	// store: queries, commits, the lock file and compiled-artifact bindings keep
575	// using the original directory even after the link changes or vanishes. A
576	// ".." following a symlink is resolved the way the kernel walk reaches it
577	// (the already-resolved link target is popped), never by lexical folding of
578	// the literal path, so it cannot select a different data directory. A
579	// not-yet-existing data directory named through a valid (possibly
580	// symlinked) parent is created under the parent's physical location. Paths
581	// to constraint definitions and input files passed to individual operations
582	// are not pinned this way — they keep being resolved against the caller's
583	// working directory at call time.
584	func Open(dir string) (*Store, error) {
585		if dir == "" {
586			return nil, invalidf("data directory must not be empty")
587		}
588		// Resolve and pin the physical location now, before anything else can
589		// change. resolveDataDir walks the argument the way the kernel reaches
590		// it — relative to the process working directory at Open time, symlinks
591		// expanded segment by segment in walk order and ".." popped in place — so
592		// a later chdir, a repointed or deleted entry link, or a ".." sitting
593		// after a symlink cannot move reads, writes, the lock or Dir onto another
594		// directory. The result is absolute and names the real directory opened.
595		dir, err := resolveDataDir(dir)
596		if err != nil {
597			return nil, fmt.Errorf("cannot resolve data directory %q: %w", dir, err)
598		}
599		if err := os.MkdirAll(dir, 0o755); err != nil {
600			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
601		}
602		lockPath := filepath.Join(dir, dirLockFile)
603		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
604		if err != nil {
605			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
606		}
607		// Serialize against other processes while we read / validate.
608		if err := lockExclusive(lock); err != nil {
609			lock.Close()
610			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
611		}
612	
613		s := &Store{dir: dir, lock: lock}
614		if err := s.loadLocked(); err != nil {
615			unlockLock(lock)
616			lock.Close()
617			return nil, err
618		}
619		// The lock is taken again per operation; holding it for the store's
620		// lifetime would forbid two open handles on one directory.
621		if err := unlockLock(lock); err != nil {
622			lock.Close()
623			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
624		}
625		return s, nil
626	}
627	
628	// Close releases the directory lock. It does not discard committed data.
629	func (s *Store) Close() error {
630		s.mu.Lock()
631		defer s.mu.Unlock()
632		if s.lock == nil {
633			return nil
634		}
635		var first error
636		if err := unlockLock(s.lock); err != nil {
637			first = err
638		}
639		if err := s.lock.Close(); err != nil && first == nil {
640			first = err
641		}
642		s.lock = nil
643		return first
644	}
