	left, err := os.ReadFile(filepath.Join(dir, dirDataFile))
	if err != nil {
		t.Fatal(err)
	}
	if string(left) != string(raw) {
		t.Fatalf("data.json changed across refused opens\nwant: %q\n got: %q", raw, left)
	}
}

