487			t.Run(label, func(t *testing.T) {
488				raw := rawJobCircuitEnvelope(circuitJSON)
489				dir := plantRawEnvelope(t, raw)
490				s, err := Open(dir)
491				if err == nil {
492					s.Close()
493					t.Fatalf("an inexact circuit match was accepted")
494				}
495				if !errors.Is(err, ErrDataCorrupt) {
