27	// seedTwoNamedFrozenSetupStore commits frozen a@1 and b@1 with a trusted setup
28	// recorded on a only. It reproduces the ambiguity that matters: a setup for a
29	// whose record also names b reads as b's setup, so a's setup vanishes while a
30	// b proof job would pass the setup gate.
31	func seedTwoNamedFrozenSetupStore(t *testing.T) string {
